function getAmmoContainerContents(container, items) {
    if (!container.system.consume.target) return null;
    contents = items.find(item => item.id === container.system.consume.target);
    return contents;
}

function getAmmoContainerQty(container, items) {
    contents = getAmmoContainerContents(container, items)
    if (!contents) return 0;
    return contents.system.quantity;
}

function getAmmoContainersToFill(actor) {
    return actor.items.filter(i => {
        if (!i.flags.cyberpunk5e) return false;
        // if (!i.flags.cyberpunk5e.type !== 'container') return false;
        if (!i.flags.cyberpunk5e.capacity) return false;
        return getAmmoContainerQty(i, actor.items) < i.flags.cyberpunk5e.capacity;
    });
}

async function createAmmo(actor, container) {
    containerProps = container.flags.cyberpunk5e;
    if (!containerProps) return null;
    ammoType = containerProps.ammo_type;
    ammoName = ammoType[0].toUpperCase() + ammoType.slice(1);
    ammoItem = ammoData[ammoType];
    ammoItem.name = ammoName.concat(" [" + container.name + "]");
    ammoItem.system.quantity = containerProps.capacity;
    items = await actor.createEmbeddedDocuments('Item', [ammoItem]);
    return items[0];
}

async function refillButton(html, actor) {
    var selectedContainerId = html.find('[id=containers]')[0].value;
    var selectedContainer = actor.items.find(i => i.id === selectedContainerId);

    var amountRefilled = selectedContainer.flags.cyberpunk5e.capacity;
    var ammoItem = actor.items.find(i => i.id === selectedContainer.system.consume.target);
    if (!ammoItem) {
        ammoItem = await createAmmo(actor, selectedContainer);
        await selectedContainer.update({'system.consume.target': ammoItem.id, 'system.consume.amount': 1})
    } else {
        amountRefilled = selectedContainer.flags.cyberpunk5e.capacity - ammoItem.system.quantity;
        await ammoItem.update({'system.quantity': selectedContainer.flags.cyberpunk5e.capacity});
    }
    let content_html = `${actor.name} has filled ${selectedContainer.name}!`;
    ChatMessage.create({content: content_html})
}

let containers = getAmmoContainersToFill(token.actor);
if (containers.length == 0) return;

let containerOptions = containers.map(c => {
    var qty = getAmmoContainerQty(c, token.actor.items);
    return `<option value=${c.id}>${c.name} [${qty}/${c.flags.cyberpunk5e.capacity}]</option>`;
}).reduce((r,opt) => r.concat(opt), '<option disabled value selected />');

let containerSelector = `
<div>
    <label>Select container to refill:</label>
    <select id="containers" name="containers">${containerOptions}</select>
</div>`
let dialogHtml = `
<div>${containerSelector}</div>
`

